import{_ as n,o as e,c as a,S as o}from"./chunks/framework.D1Ss-Xl7.js";const m=JSON.parse('{"title":"使用Docker运行node项目","description":"使用 Docker 容器化开发和部署，是当今的主流。因为程序跑在了容器之内，我们再也不用担心安装各种依赖和版本管理。接下来就来介绍如何使用 Docker 开发自己的 node 项目。","frontmatter":{"title":"使用Docker运行node项目","date":"2019-09-23 22:43","comments":true,"archives":2019,"tags":["docker"]},"headers":[],"relativePath":"posts/2019-09-23-node-docker/index.md","filePath":"posts/2019/2019-09-23-node-docker.md"}'),l={name:"posts/2019-09-23-node-docker/index.md"};function p(r,s,c,i,t,d){return e(),a("div",null,[...s[0]||(s[0]=[o(`<p>使用 Docker 容器化开发和部署，是当今的主流。因为程序跑在了容器之内，我们再也不用担心安装各种依赖和版本管理。接下来就来介绍如何使用 Docker 开发自己的 node 项目。</p><h2 id="使用-docker-compose-管理多个-docker" tabindex="-1">使用 docker-compose 管理多个 Docker <a class="header-anchor" href="#使用-docker-compose-管理多个-docker" aria-label="Permalink to &quot;使用 docker-compose 管理多个 Docker&quot;">​</a></h2><p>很多情况下，一个 Docker 是满足不了需求的，有时候还要使用 MySQL 数据库，有时候还要使用 redis。这时候就需要使用 docker-compose 来管理多个 Docker。docker-compose 的使用也很简单，只要在项目根目录下建立一个<code>docker-compose.yml</code>文件即可。关于 YAML 的学习，可以参考<a href="https://www.codeproject.com/Articles/1214409/Learn-YAML-in-five-minutes" target="_blank" rel="noreferrer">Learn YAML in five minutes!</a>。</p><h2 id="docker-compose-内容定义" tabindex="-1">docker-compose 内容定义 <a class="header-anchor" href="#docker-compose-内容定义" aria-label="Permalink to &quot;docker-compose 内容定义&quot;">​</a></h2><p>首先我们需要声明版本号<code>version</code>，不同的 Docker 版本对 docker-compose 的版本支持也不一样，可以参考官方的文档进行<a href="https://docs.docker.com/compose/compose-file/" target="_blank" rel="noreferrer">对照</a>。 然后声明<code>services</code>，service 下的每一个声明都是一个 Docker 的实例。下面介绍一个实际例子：</p><div class="language-yaml line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#22863A;">version</span><span style="color:#24292E;">: </span><span style="color:#032F62;">&#39;3.7&#39;</span></span>
<span class="line"><span style="color:#22863A;">services</span><span style="color:#24292E;">:</span></span>
<span class="line"><span style="color:#22863A;">  pg</span><span style="color:#24292E;">:</span></span>
<span class="line"><span style="color:#22863A;">    image</span><span style="color:#24292E;">: </span><span style="color:#032F62;">postgres:9.5</span></span>
<span class="line"><span style="color:#22863A;">    ports</span><span style="color:#24292E;">:</span></span>
<span class="line"><span style="color:#24292E;">      - </span><span style="color:#032F62;">&#39;\${DB_EXPORT_PORT-54320}:5432&#39;</span></span>
<span class="line"><span style="color:#22863A;">    environment</span><span style="color:#24292E;">:</span></span>
<span class="line"><span style="color:#22863A;">      POSTGRES_USER</span><span style="color:#24292E;">: </span><span style="color:#032F62;">&#39;\${DB_USER-postgres}&#39;</span></span>
<span class="line"><span style="color:#22863A;">      POSTGRES_PASSWORD</span><span style="color:#24292E;">: </span><span style="color:#032F62;">&#39;\${DB_PASS-123456}&#39;</span></span>
<span class="line"><span style="color:#22863A;">      POSTGRES_DB</span><span style="color:#24292E;">: </span><span style="color:#032F62;">&#39;\${DB_NAME-dmhy_indexer}&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#22863A;">  main</span><span style="color:#24292E;">:</span></span>
<span class="line"><span style="color:#22863A;">    build</span><span style="color:#24292E;">: </span><span style="color:#005CC5;">.</span></span>
<span class="line"><span style="color:#22863A;">    cap_add</span><span style="color:#24292E;">:</span></span>
<span class="line"><span style="color:#24292E;">      - </span><span style="color:#032F62;">SYS_ADMIN</span><span style="color:#6A737D;"> # ref https://github.com/GoogleChrome/puppeteer/blob/v1.12.1/docs/troubleshooting.md#running-puppeteer-in-docker</span></span>
<span class="line"><span style="color:#22863A;">    image</span><span style="color:#24292E;">: </span><span style="color:#032F62;">&#39;indexer&#39;</span></span>
<span class="line"><span style="color:#22863A;">    command</span><span style="color:#24292E;">: </span><span style="color:#032F62;">yarn start</span></span>
<span class="line"><span style="color:#22863A;">    ports</span><span style="color:#24292E;">:</span></span>
<span class="line"><span style="color:#24292E;">      - </span><span style="color:#032F62;">&#39;9229:9229&#39;</span></span>
<span class="line"><span style="color:#22863A;">    environment</span><span style="color:#24292E;">:</span></span>
<span class="line"><span style="color:#22863A;">      INDEXER_MODE</span><span style="color:#24292E;">: </span><span style="color:#032F62;">&#39;\${INDEXER_MODE-dmhy}&#39;</span></span>
<span class="line"><span style="color:#22863A;">      DB_HOST</span><span style="color:#24292E;">: </span><span style="color:#032F62;">&#39;\${DB_HOST-pg}&#39;</span></span>
<span class="line"><span style="color:#22863A;">      DB_PORT</span><span style="color:#24292E;">: </span><span style="color:#032F62;">&#39;\${DB_PORT-5432}&#39;</span></span>
<span class="line"><span style="color:#22863A;">      DB_USER</span><span style="color:#24292E;">: </span><span style="color:#032F62;">&#39;\${DB_USER-postgres}&#39;</span></span>
<span class="line"><span style="color:#22863A;">      DB_NAME</span><span style="color:#24292E;">: </span><span style="color:#032F62;">&#39;\${DB_NAME-dmhy_indexer}&#39;</span></span>
<span class="line"><span style="color:#22863A;">      DB_PASS</span><span style="color:#24292E;">: </span><span style="color:#032F62;">&#39;\${DB_PASS-123456}&#39;</span></span>
<span class="line"><span style="color:#22863A;">    volumes</span><span style="color:#24292E;">:</span></span>
<span class="line"><span style="color:#24292E;">      - </span><span style="color:#032F62;">&#39;.:/irohalab/indexer&#39;</span></span>
<span class="line"><span style="color:#24292E;">      - </span><span style="color:#032F62;">&#39;/irohalab/indexer/node_modules&#39;</span></span>
<span class="line"><span style="color:#24292E;">      - </span><span style="color:#032F62;">&#39;/irohalab/indexer/dist&#39;</span></span>
<span class="line"><span style="color:#22863A;">    depends_on</span><span style="color:#24292E;">:</span></span>
<span class="line"><span style="color:#24292E;">      - </span><span style="color:#032F62;">pg</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br></div></div><p>这个配置来源于<a href="https://github.com/irohalab/indexer" target="_blank" rel="noreferrer">indexer</a>。我们定义了两个 Service。第一个是数据库 Postgres，第二个便是我们的主项目。首先，我们来看数据库配置，声明了使用官方的<code>postgres:9.5</code>镜像，并映射数据库 5432 端口到主机。这里<code>\${DB_EXPORT_PORT-54320}</code>的意思是读取环境变量<code>DB_EXPORT_PORT</code>，如果没有的话就使用默认值<code>54320</code>，这也是 YAML 语法的一部分。接下来又定义了数据库启动需要的环境变量参数。</p><p>重点是配置的 main 项目，由于 main 项目使用了自定义的 Dockerfile，所以我们需要结合 Dockerfile 的配置来讲述。</p><div class="language-dockerfile line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">dockerfile</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">FROM</span><span style="color:#24292E;"> node:10.16.3-stretch</span></span>
<span class="line"><span style="color:#D73A49;">RUN</span><span style="color:#24292E;"> apt-get update -qq &amp;&amp; apt-get install -y gconf-service libasound2 libatk1.0-0 libatk-bridge2.0-0 libc6 libcairo2 libcups2 libdbus-1-3 libexpat1 libfontconfig1 libgcc1 libgconf-2-4 libgdk-pixbuf2.0-0 libglib2.0-0 libgtk-3-0 libnspr4 libpango-1.0-0 libpangocairo-1.0-0 libstdc++6 libx11-6 libx11-xcb1 libxcb1 libxcomposite1 libxcursor1 libxdamage1 libxext6 libxfixes3 libxi6 libxrandr2 libxrender1 libxss1 libxtst6 ca-certificates fonts-liberation libappindicator1 libnss3 lsb-release xdg-utils wget</span></span>
<span class="line"><span style="color:#D73A49;">WORKDIR</span><span style="color:#24292E;"> /irohalab/indexer</span></span>
<span class="line"><span style="color:#D73A49;">RUN</span><span style="color:#24292E;"> chown -R node:node /irohalab/indexer</span></span>
<span class="line"><span style="color:#D73A49;">RUN</span><span style="color:#24292E;"> usermod -a -G audio,video node</span></span>
<span class="line"><span style="color:#D73A49;">USER</span><span style="color:#24292E;"> node</span></span>
<span class="line"><span style="color:#D73A49;">COPY</span><span style="color:#24292E;"> package.json yarn.lock ./</span></span>
<span class="line"><span style="color:#D73A49;">RUN</span><span style="color:#24292E;"> yarn install</span></span>
<span class="line"><span style="color:#D73A49;">RUN</span><span style="color:#24292E;"> mkdir dist</span></span>
<span class="line"><span style="color:#D73A49;">COPY</span><span style="color:#24292E;"> . .</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><p>Dockerfile 的第一句话一定是 FROM，代表着是基于哪个官方镜像来自定义。我们基于 node 的 10.16.3 版本来定制镜像，第一步是安装项目额外需要的依赖，第二步是设定工作目录。由于当前项目需要非 root 权限的用户来运行，所以我们需要之后改变权限，ndoe 镜像官方提供了非 root 用户<code>node</code>，所以我们就把工作目录的权限改成了<code>node</code>。接下来是添加到需要的组，之后就是切换用户到<code>node</code>。 切换之前默认 Docker 是使用 root 权限运行的，切换之后就是<code>node</code>用户了，我们 copy 需要的文件之后，执行<code>yarn install</code>来安装，由于存在主机是 Mac，但是 Docker 是 Linux 的情况，所以主机的<code>node_modules</code>并不能直接用，所以我们需要在 Docker 中安装依赖。接下来又创建了一个 dist 目录，然后复制了整个项目。为什么创建<code>dist</code>目录接下来要讲。</p><h2 id="使用非-root-权限运行" tabindex="-1">使用非 root 权限运行 <a class="header-anchor" href="#使用非-root-权限运行" aria-label="Permalink to &quot;使用非 root 权限运行&quot;">​</a></h2><p>这部分是 Docker 配置最折腾的地方。因为 Docker 默认是用 root 权限运行的，所以切换到非 root 权限执行程序就会经常遇到 permission denied 的问题。接下来就要讲述 main 部分的配置参数，<code>build: .</code>在当前目录下 build，就是寻找当前目录下的 Dockerfile 并进行 build，<code>cap_add</code>参数是添加<code>Linux capabilities</code>。这部分可以参考<a href="https://docs.docker.com/engine/reference/run/" target="_blank" rel="noreferrer">Runtime privilege and Linux capabilities</a>。之所以添加是因为<a href="https://github.com/GoogleChrome/puppeteer/blob/v1.12.1/docs/troubleshooting.md#running-puppeteer-in-docker" target="_blank" rel="noreferrer">puppeteer</a>需要，apt-get 安装的依赖也是。重点是<code>volumes</code>配置，第一行代表当前目录映射到<code>/irohalab/indexer</code>也就是我们设定的工作目录位置。第二行和第三行是为了移除对<code>node_modules</code>文件夹和<code>dist</code>文件夹的映射。但如果 Docker 里没有这两个文件夹就会由 root 来创建，所以我才特地<code>mkdir dist</code>。否则普通用户又会没有权限了。<code>depends_on</code>代表当前镜像的依赖，同时声明依赖之后，Docker 内部之间可以通讯，主机名就是<code>services</code>里定义的名字。</p><h2 id="使用-dockerignore" tabindex="-1">使用 dockerignore <a class="header-anchor" href="#使用-dockerignore" aria-label="Permalink to &quot;使用 dockerignore&quot;">​</a></h2><p>dockerignore 和 gitignore 的用法非常类似，当指定了某些文件或文件夹的时候，在执行 COPY 等命令的时候就会忽略这些文件或文件夹。</p><h2 id="清理-docker" tabindex="-1">清理 Docker <a class="header-anchor" href="#清理-docker" aria-label="Permalink to &quot;清理 Docker&quot;">​</a></h2><p>由于开发过程中各种调试和重新 build，导致产生的无用的镜像数据特别多，所以需要经常清理。官方文档有详细的<a href="https://docs.docker.com/config/pruning/" target="_blank" rel="noreferrer">清理说明</a>。</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6F42C1;">$</span><span style="color:#032F62;"> docker</span><span style="color:#032F62;"> image</span><span style="color:#032F62;"> prune</span><span style="color:#005CC5;"> -a</span></span>
<span class="line"><span style="color:#6F42C1;">$</span><span style="color:#032F62;"> docker</span><span style="color:#032F62;"> system</span><span style="color:#032F62;"> prune</span><span style="color:#005CC5;"> --volumes</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>第一个命令会清除所有的镜像，不管有没有使用。第二个命令会清除所有不相关或不使用的 Docker 数据。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>Docker 很强大，但是用起来也没有那么容易。需要不断的尝试，去摸索各种选项的配置和使用。</p><h2 id="引用" tabindex="-1">引用 <a class="header-anchor" href="#引用" aria-label="Permalink to &quot;引用&quot;">​</a></h2><p><a href="https://www.digitalocean.com/community/tutorials/containerizing-a-node-js-application-for-development-with-docker-compose" target="_blank" rel="noreferrer">Containerizing a Node.js Application for Development With Docker Compose</a></p><p><a href="https://www.digitalocean.com/community/tutorials/how-to-build-a-node-js-application-with-docker" target="_blank" rel="noreferrer">How To Build a Node.js Application with Docker</a></p><p><a href="https://stackoverflow.com/questions/29181032/add-a-volume-to-docker-but-exclude-a-sub-folder" target="_blank" rel="noreferrer">Add a volume to Docker, but exclude a sub-folder</a></p><p><a href="https://docs.docker.com/engine/reference/builder/#dockerignore-file" target="_blank" rel="noreferrer">.dockerignore file</a></p>`,25)])])}const u=n(l,[["render",p]]);export{m as __pageData,u as default};
